class TtitraceEvent(object):
    """
    TTI trace event.

    Usage:

    * Read a file with eventDecoder decoded json data TTI events and handle each event

            Code::

                file_name = '/tmp/ttitrace.json'

                with open(file_name, 'rb') as file_obj:
                    for event in TtitraceReader(
                          file_obj=file_obj)):
                        # handle event

    * Pretty print the event data

        Code::

            if event.type == "dssSlotTypeData":
                print(json.dumps(event.data, indent=4))

        Output::

                {
                    "eventHeader": {
                        "onAirTime": {
                            "sfn": 207,
                            "slot": 8
                        },
                        "rnti": 0,
                        "physCellId": 50
                    },
                    "slotType": "DSSSLOTTYPE_REGULAR"
                }


    * Access an TTI event parameter via event.data

        Code::

                print(event.data["slotType"])

        Output::

            "DSSSLOTTYPE_REGULAR"

    * Simplified access to an TTI event parameter via event[...]

        Code::

                print(event["physCellId"])

        Output::

            50
    """
    def __init__(self, event_data):
        """
        Create a TtitraceEvent.

        A TtitraceEvent wraps a decoded TTI trace event, represented as a nested dict in event.data.
        It offers easy access methods like event.type and event[key].

        :param dict event_data:  a decoded event (nested dictionary)
        """
        self._event_data = event_data

    def __getitem__(self, key_name):
        """
        Return the field value for a field name, that occurs anywhere in the nested event data dictionaries.

        :param str key_name:    key name of an event field
        :return:            return the value for the key
        """
        return _get_value_from_key(
            event_data=self._event_data,
            key_name=key_name)

    def _get_type(self):
        """
        Return the type of the event.
        """
        event_type = list(self._event_data.keys())[0]
        return event_type

    def _get_event_data_body(self):
        """
        Return body of event
        """
        return list(self._event_data.values())[0]["body"]

    type = property(_get_type)
    data = property(_get_event_data_body)


def _get_value_from_key(event_data, key_name):
    """
    Get field value for a field name.

    The field name can occur anywhere in the nested dictionaries of the event data and is recursively searched for.

    :param dict event_data:      decoded event data (dictionary)
    :param str key_name:        name of a field within the event data
    :return:                value for the key
    """
    for key, value in event_data.items():
        if key == key_name:
            return value
        if isinstance(value, dict):
            result = _get_value_from_key(
                event_data=value,
                key_name=key_name)
            if result is not None:
                return result
